memory_patch_definition.source:
#define MDFN_MEMPATCH_NAME_LEN       128
#define MDFN_MEMPATCH_CONDITIONS_LEN 256

typedef struct MemoryPatch
{
   char     name      [MDFN_MEMPATCH_NAME_LEN];
   char     conditions[MDFN_MEMPATCH_CONDITIONS_LEN];
   uint32_t addr;
   uint64_t val;
   uint64_t compare;
   uint32_t mltpl_count;
   uint32_t mltpl_addr_inc;
   uint64_t mltpl_val_inc;
   uint32_t copy_src_addr;
   uint32_t copy_src_addr_inc;
   unsigned length;
   bool     bigendian;
   bool     status; /* (in)active */
   unsigned icount;
   char     type; /* 'R' replace, 'S' substitute(GG), 'C' substitute+compare,
                   * 'T' copy/transfer, 'A' add(variant of R) */
} MemoryPatch;

gs_condition.source:
static void GSCondCode(MemoryPatch* patch, const char* cc, const unsigned len, const uint32_t addr, const uint16_t val)
{
   char tmp[256];

   if (patch->conditions[0] != 0)
      strlcat(patch->conditions, ", ", sizeof(patch->conditions));

   if (len == 2)
      snprintf(tmp, 256, "%u L 0x%08x %s 0x%04x", len, addr, cc, val & 0xFFFFU);
   else
      snprintf(tmp, 256, "%u L 0x%08x %s 0x%02x", len, addr, cc, val & 0xFFU);

   strlcat(patch->conditions, tmp, sizeof(patch->conditions));
}

decode_gs.source:
static bool DecodeGS(const char *cheat_string, MemoryPatch *patch)
{
   uint64_t code = 0;
   unsigned nybble_count = 0;
   const size_t len = strlen(cheat_string);
   uint8_t  code_type;
   uint64_t cl;
   unsigned i;

   for(i = 0; i < len; i++)
   {
      if(cheat_string[i] == ' ' || cheat_string[i] == '-' || cheat_string[i] == ':' || cheat_string[i] == '+')
         continue;

      nybble_count++;
      code <<= 4;

      if(cheat_string[i] >= '0' && cheat_string[i] <= '9')
         code |= cheat_string[i] - '0';
      else if(cheat_string[i] >= 'a' && cheat_string[i] <= 'f')
         code |= cheat_string[i] - 'a' + 0xA;
      else if(cheat_string[i] >= 'A' && cheat_string[i] <= 'F')
         code |= cheat_string[i] - 'A' + 0xA;
      else
      {
         if(cheat_string[i] & 0x80)
            log_cb(RETRO_LOG_ERROR, "Invalid character in GameShark code..\n");
         else
            log_cb(RETRO_LOG_ERROR, "Invalid character in GameShark code: %c.\n", cheat_string[i]);
         return false;
      }
   }

   if(nybble_count != 12)
   {
      log_cb(RETRO_LOG_ERROR, "GameShark code is of an incorrect length.\n");
      return false;
   }

   code_type = code >> 40;
   cl = code & 0xFFFFFFFFFFULL;

   patch->bigendian = false;
   patch->compare = 0;

   if(patch->type == 'T')
   {
      if(code_type != 0x80)
      log_cb(RETRO_LOG_ERROR, "Unrecognized GameShark code type for second part to copy bytes code.\n");

      patch->addr = cl >> 16;
      return(false);
   }

   switch(code_type)
   {
   default:
      log_cb(RETRO_LOG_ERROR, "GameShark code type 0x%02X is currently not supported.\n", code_type);
      return(false);

   // TODO:
   case 0x10:   // 16-bit increment
      patch->length = 2;
      patch->type = 'A';
      patch->addr = cl >> 16;
      patch->val = cl & 0xFFFF;
      return(false);

   case 0x11:   // 16-bit decrement
      patch->length = 2;
      patch->type = 'A';
      patch->addr = cl >> 16;
      patch->val = (0 - cl) & 0xFFFF;
      return(false);

   case 0x20:   // 8-bit increment
      patch->length = 1;
      patch->type = 'A';
      patch->addr = cl >> 16;
      patch->val = cl & 0xFF;
      return(false);

   case 0x21:   // 8-bit decrement
      patch->length = 1;
      patch->type = 'A';
      patch->addr = cl >> 16;
      patch->val = (0 - cl) & 0xFF;
      return(false);
   //
   //
   //

   case 0x30:   // 8-bit constant
      patch->length = 1;
      patch->type = 'R';
      patch->addr = cl >> 16;
      patch->val = cl & 0xFF;
      return(false);

   case 0x80:   // 16-bit constant
      patch->length = 2;
      patch->type = 'R';
      patch->addr = cl >> 16;
      patch->val = cl & 0xFFFF;
      return(false);

   case 0x50:   // Repeat thingy
   {
      const uint8_t wcount = (cl >> 24) & 0xFF;
      const uint8_t addr_inc = (cl >> 16) & 0xFF;
      const uint8_t val_inc = (cl >> 0) & 0xFF;

      patch->mltpl_count = wcount;
      patch->mltpl_addr_inc = addr_inc;
      patch->mltpl_val_inc = val_inc;
   }
   return(true);

   case 0xC2:   // Copy
   {
      const uint16_t ccount = cl & 0xFFFF;

      patch->type = 'T';
      patch->val = 0;
      patch->length = 1;

      patch->copy_src_addr = cl >> 16;
      patch->copy_src_addr_inc = 1;

      patch->mltpl_count = ccount;
      patch->mltpl_addr_inc = 1;
      patch->mltpl_val_inc = 0;
   }
   return(true);

  case 0xD0:   // 16-bit == condition
   GSCondCode(patch, "==", 2, cl >> 16, cl);
   return(true);

  case 0xD1:   // 16-bit != condition
   GSCondCode(patch, "!=", 2, cl >> 16, cl);
   return(true);

  case 0xD2:   // 16-bit < condition
   GSCondCode(patch, "<", 2, cl >> 16, cl);
   return(true);

  case 0xD3:   // 16-bit > condition
   GSCondCode(patch, ">", 2, cl >> 16, cl);
   return(true);



  case 0xE0:   // 8-bit == condition
   GSCondCode(patch, "==", 1, cl >> 16, cl);
   return(true);

  case 0xE1:   // 8-bit != condition
   GSCondCode(patch, "!=", 1, cl >> 16, cl);
   return(true);

  case 0xE2:   // 8-bit < condition
   GSCondCode(patch, "<", 1, cl >> 16, cl);
   return(true);

  case 0xE3:   // 8-bit > condition
   GSCondCode(patch, ">", 1, cl >> 16, cl);
   return(true);

 }
}

retro_cheat_set.source:
void retro_cheat_set(unsigned index, bool enabled, const char * codeLine)
{
   const CheatFormatStruct* cf = CheatFormats;
   char name[256];
   /* PSX cheat codes are tokens of hex digits.  Each token is at
    * most 12 chars (full code) or 8 chars (half-code; two of these
    * concatenate to a full code).  An entire codeLine yields one
    * token roughly per 4 chars, so a 64-token cap covers everything
    * realistic.  Bounded buffer avoids dynamic allocation entirely. */
   char codeParts[64][16];
   int  numParts = 0;
   int  matchLength = 0;
   int  cursor;
   char part[32];
   MemoryPatch patch;

   if (!codeLine)
      return;

   /* Break the code into Parts */
   for (cursor = 0; ; cursor++)
   {
      if (ISHEXDEC)
         matchLength++;
      else
      {
         if (matchLength)
         {
            int copy_len = matchLength;
            if (copy_len >= (int)sizeof(codeParts[0]))
               copy_len = (int)sizeof(codeParts[0]) - 1;
            if (numParts < (int)(sizeof(codeParts) / sizeof(codeParts[0])))
            {
               memcpy(codeParts[numParts], codeLine + cursor - matchLength, copy_len);
               codeParts[numParts][copy_len] = '\0';
               numParts++;
            }
            matchLength = 0;
         }
      }
      if (!codeLine[cursor])
         break;
   }

   MemoryPatch_Init(&patch);
   for (cursor = 0; cursor < numParts; cursor++)
   {
      size_t plen;
      strlcpy(part, codeParts[cursor], sizeof(part));
      plen = strlen(part);
      if (plen == 8 && cursor + 1 < numParts)
      {
         strlcat(part, codeParts[++cursor], sizeof(part));
         plen = strlen(part);
      }
      if (plen == 12)
      {
         /* Decode the cheat. DecodeCheat returns false on bad codes;
          * MDFNI_AddCheat does not throw. */
         if (!cf->DecodeCheat(part, &patch))
         {
            /* Generate a name */
            snprintf(name, sizeof(name), "cheat_%i_%i", index, cursor);

            /* Set parameters */
            strlcpy(patch.name, name, sizeof(patch.name));
            patch.status = enabled;

            MDFNI_AddCheat(&patch);
            MemoryPatch_Init(&patch);
         }
      }
   }
}

test_conditions.source:
static bool TestConditions(const char *string)
{
   char         address[64];
   char         operation[64];
   char         value[64];
   char         endian;
   unsigned int bytelen;
   bool         passed = true;

   while (   passed
          && sscanf(string, "%u %c %63s %63s %63s",
                   &bytelen, &endian, address, operation, value) == 5)
   {
      uint32_t v_address;
      uint64_t v_value;
      uint64_t value_at_address;
      unsigned int x;

      if (address[0] == '0' && address[1] == 'x')
         v_address = strtoul(address + 2, NULL, 16);
      else
         v_address = strtoul(address, NULL, 10);

      if (value[0] == '0' && value[1] == 'x')
         v_value = strtoull(value + 2, NULL, 16);
      else
         v_value = strtoull(value, NULL, 0);

      value_at_address = 0;
      for (x = 0; x < bytelen; x++)
      {
         unsigned int shiftie = (endian == 'B') ? (bytelen - 1 - x) * 8 : x * 8;
         value_at_address |= (uint64_t)PSX_MemPeek8(v_address + x) << shiftie;
      }

      if      (!strcmp(operation, ">="))  { if (!(value_at_address >= v_value)) passed = false; }
      else if (!strcmp(operation, "<="))  { if (!(value_at_address <= v_value)) passed = false; }
      else if (!strcmp(operation, ">"))   { if (!(value_at_address >  v_value)) passed = false; }
      else if (!strcmp(operation, "<"))   { if (!(value_at_address <  v_value)) passed = false; }
      else if (!strcmp(operation, "==")) { if (!(value_at_address == v_value)) passed = false; }
      else if (!strcmp(operation, "!=")) { if (!(value_at_address != v_value)) passed = false; }
      else if (!strcmp(operation, "&"))   { if (!(value_at_address &  v_value)) passed = false; }
      else if (!strcmp(operation, "!&"))  { if  ((value_at_address &  v_value)) passed = false; }
      else if (!strcmp(operation, "^"))   { if (!(value_at_address ^  v_value)) passed = false; }
      else if (!strcmp(operation, "!^"))  { if  ((value_at_address ^  v_value)) passed = false; }
      else if (!strcmp(operation, "|"))   { if (!(value_at_address |  v_value)) passed = false; }
      else if (!strcmp(operation, "!|"))  { if  ((value_at_address |  v_value)) passed = false; }

      string = strchr(string, ',');
      if (!string)
         break;
      string++;
   }

   return passed;
}

apply_periodic.source:
void MDFNMP_ApplyPeriodicCheats(void)
{
   size_t ci;

   if (!CheatsActive)
      return;

   for (ci = 0; ci < cheats_count; ci++)
   {
      MemoryPatch *chit = &cheats[ci];

      if (!chit->status)
         continue;
      if (chit->type != 'R' && chit->type != 'A' && chit->type != 'T')
         continue;
      if (chit->conditions[0] != 0 && !TestConditions(chit->conditions))
         continue;

      {
         uint32_t mltpl_count   = chit->mltpl_count;
         uint32_t mltpl_addr    = chit->addr;
         uint64_t mltpl_val     = chit->val;
         uint32_t copy_src_addr = chit->copy_src_addr;

         while (mltpl_count--)
         {
            uint8_t carry = 0;
            unsigned int x;

            for (x = 0; x < chit->length; x++)
            {
               const uint32_t tmpaddr = chit->bigendian
                  ? (mltpl_addr + chit->length - 1 - x)
                  : (mltpl_addr + x);
               const uint8_t  tmpval  = mltpl_val >> (x * 8);

               if (chit->type == 'A')
               {
                  const unsigned t = PSX_MemPeek8(tmpaddr) + tmpval + carry;
                  carry = t >> 8;
                  PSX_MemPoke8(tmpaddr, (uint8_t)t);
               }
               else if (chit->type == 'T')
               {
                  const uint8_t cv = PSX_MemPeek8(chit->bigendian
                        ? (copy_src_addr + chit->length - 1 - x)
                        : (copy_src_addr + x));
                  PSX_MemPoke8(tmpaddr, cv);
               }
               else
                  PSX_MemPoke8(tmpaddr, tmpval);
            }
            mltpl_addr    += chit->mltpl_addr_inc;
            mltpl_val     += chit->mltpl_val_inc;
            copy_src_addr += chit->copy_src_addr_inc;
         }
      }
   }
}
